exercises.solution:
function padariaAberta(dia, hora) {
  const diaFechado = dia === 'segunda' || dia === 'feriado';
  const noHorario = hora >= 6 && hora < 20;
  return !diaFechado && noHorario;
}

function mostrar(dia, hora) {
  if (padariaAberta(dia, hora)) {
    console.log(`${dia} às ${hora}h: aberta`);
  } else {
    console.log(`${dia} às ${hora}h: fechada`);
  }
}

